/// Kataklarni chizadi: yog'och tolalari, marmar tomirlari yoki tekis rang.

// ---------------------------------------------------------------------------
// Giperrealistik yog'och doska: yagona shpon yuzasi, har katakda o'z tolalari,
// g'ovaklar, kataklar orasidagi tikuv va laklangan yaltiroqlik.
// ---------------------------------------------------------------------------

extension _AlphaD on Color {
  Color alphaD(double a) => withAlpha((a.clamp(0.0, 1.0) * 255).round());
}

class _WoodBoardPainter extends CustomPainter {
  const _WoodBoardPainter();

  // Och katak: zarg'aldoq/chinor shponi; to'q katak: yong'oq (walnut) shponi.
  static const _lightA = Color(0xFFF1DDB3);
  static const _lightB = Color(0xFFDDBB86);
  static const _darkA = Color(0xFF8F5C36);
  static const _darkB = Color(0xFF5C3519);

  @override
  void paint(Canvas canvas, Size size) {
    final cell = size.width / 8;
    for (var r = 0; r < 8; r++) {
      for (var c = 0; c < 8; c++) {
        final light = (r + c) % 2 == 0;
        _square(canvas, Offset(c * cell, r * cell), cell, light, r * 8 + c);
      }
    }
    // Kataklar orasidagi nozik tikuv chiziqlari
    final joint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = math.max(0.6, cell * 0.012)
      ..color = const Color(0x40200E02);
    for (var i = 1; i < 8; i++) {
      canvas.drawLine(Offset(i * cell, 0), Offset(i * cell, size.height), joint);
      canvas.drawLine(Offset(0, i * cell), Offset(size.width, i * cell), joint);
    }
  }

  void _square(Canvas canvas, Offset o, double cell, bool light, int seed) {
    final rnd = math.Random(seed * 104729 + (light ? 17 : 31));
    final rect = Rect.fromLTWH(o.dx, o.dy, cell, cell);
    final tone = (rnd.nextDouble() - 0.5) * 0.16; // har katak biroz boshqacha rang
    Color shade(Color c) => tone >= 0
        ? Color.lerp(c, Colors.white, tone * 0.5)!
        : Color.lerp(c, Colors.black, -tone * 0.7)!;
    final a = shade(light ? _lightA : _darkA);
    final b = shade(light ? _lightB : _darkB);
    final horizontal = rnd.nextBool(); // shponning yo'nalishi har katakda har xil

    canvas.save();
    canvas.clipRect(rect);

    // Asosiy rang (tola bo'ylab o'zgaruvchan)
    canvas.drawRect(
      rect,
      Paint()
        ..shader = LinearGradient(
          begin: horizontal ? Alignment.topCenter : Alignment.centerLeft,
          end: horizontal ? Alignment.bottomCenter : Alignment.centerRight,
          colors: [a, Color.lerp(a, b, 0.3)!, a],
          stops: const [0, 0.5, 1],
        ).createShader(rect),
    );

    // Keng yumshoq yillik halqa bantlari
    final band = Paint()..style = PaintingStyle.stroke;
    for (var i = 0; i < 5; i++) {
      final t = rnd.nextDouble();
      band
        ..strokeWidth = cell * (0.05 + rnd.nextDouble() * 0.12)
        ..color = (light ? const Color(0xFF8A5A22) : const Color(0xFF1E0E03))
            .alphaD(0.05 + rnd.nextDouble() * 0.06);
      final path = Path();
      if (horizontal) {
        final y = o.dy + cell * t;
        path.moveTo(o.dx, y);
        path.cubicTo(o.dx + cell * 0.3, y + cell * (rnd.nextDouble() - 0.5) * 0.16,
            o.dx + cell * 0.7, y + cell * (rnd.nextDouble() - 0.5) * 0.16, o.dx + cell, y);
      } else {
        final x = o.dx + cell * t;
        path.moveTo(x, o.dy);
        path.cubicTo(x + cell * (rnd.nextDouble() - 0.5) * 0.16, o.dy + cell * 0.3,
            x + cell * (rnd.nextDouble() - 0.5) * 0.16, o.dy + cell * 0.7, x, o.dy + cell);
      }
      canvas.drawPath(path, band);
    }

    // Ingichka tolalar
    final fine = Paint()..style = PaintingStyle.stroke;
    final n = 26 + rnd.nextInt(10);
    for (var i = 0; i < n; i++) {
      final t = (i + rnd.nextDouble()) / n;
      final amp = cell * (0.004 + rnd.nextDouble() * 0.018);
      final ph = rnd.nextDouble() * math.pi * 2;
      final f = 1.2 + rnd.nextDouble() * 2.2;
      final dark = rnd.nextDouble() < 0.72;
      fine
        ..strokeWidth = math.max(0.35, cell * (0.0035 + rnd.nextDouble() * 0.009))
        ..color = (dark
                ? (light ? const Color(0xFF7A4A1C) : const Color(0xFF1A0B02))
                : (light ? const Color(0xFFFFF3D6) : const Color(0xFFC08A5A)))
            .alphaD(dark ? 0.10 + rnd.nextDouble() * 0.16 : 0.10 + rnd.nextDouble() * 0.10);
      final path = Path();
      const steps = 10;
      for (var k = 0; k <= steps; k++) {
        final u = k / steps;
        final w = math.sin(u * math.pi * f + ph) * amp +
            math.sin(u * math.pi * 5.3 + ph * 2) * amp * 0.35;
        final x = horizontal ? o.dx + cell * u : o.dx + cell * t + w;
        final y = horizontal ? o.dy + cell * t + w : o.dy + cell * u;
        if (k == 0) {
          path.moveTo(x, y);
        } else {
          path.lineTo(x, y);
        }
      }
      canvas.drawPath(path, fine);
    }

    // G'ovaklar (mayda qora chiziqchalar)
    final pore = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeWidth = math.max(0.4, cell * 0.006)
      ..color = (light ? const Color(0xFF5A3510) : const Color(0xFF0E0501))
          .alphaD(0.30);
    for (var i = 0; i < 34; i++) {
      final x = o.dx + rnd.nextDouble() * cell;
      final y = o.dy + rnd.nextDouble() * cell;
      final len = cell * (0.015 + rnd.nextDouble() * 0.05);
      canvas.drawLine(Offset(x, y),
          horizontal ? Offset(x + len, y) : Offset(x, y + len), pore);
    }

    // Ba'zi kataklarda kichik chigal (o'zak) belgisi
    if (rnd.nextDouble() < 0.12) {
      final c = Offset(o.dx + cell * (0.25 + rnd.nextDouble() * 0.5),
          o.dy + cell * (0.25 + rnd.nextDouble() * 0.5));
      for (var k = 1; k <= 3; k++) {
        canvas.drawOval(
          Rect.fromCenter(
              center: c,
              width: cell * 0.05 * k * (horizontal ? 1.8 : 1),
              height: cell * 0.05 * k * (horizontal ? 1 : 1.8)),
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = math.max(0.4, cell * 0.006)
            ..color = (light ? const Color(0xFF6B3E12) : const Color(0xFF120601))
                .alphaD(0.28 - k * 0.05),
        );
      }
    }

    // Katak chetidagi yengil yorug'lik/soya (inleyning ko'tarilgan qirrasi)
    final edge = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = math.max(0.6, cell * 0.014);
    edge.color = const Color(0x14000000);
    canvas.drawRect(rect.deflate(0.5), edge);
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _WoodBoardPainter old) => false;
}

/// Laklangan yuza: yumshoq nur yaltirashi va chetlarda qorayish.
class _LacquerPainter extends CustomPainter {
  const _LacquerPainter();
  @override
  void paint(Canvas canvas, Size size) {
    // Xiralik/yaltirash olib tashlandi: doska yuzasi toza ko'rinadi.
  }

  @override
  bool shouldRepaint(covariant _LacquerPainter old) => false;
}

/// Doska ramkasi: uzun yong'oq tolalari va qirra yaltirashi.
class _WoodFramePainter extends CustomPainter {
  const _WoodFramePainter();
  @override
  void paint(Canvas canvas, Size size) {
    final rect = Offset.zero & size;
    final rnd = math.Random(777);
    final rr = RRect.fromRectAndRadius(rect, Radius.circular(size.width * 0.012));
    canvas.save();
    canvas.clipRRect(rr);
    canvas.drawRect(
      rect,
      Paint()
        ..color = const Color(0xFF7A4B28),
    );
    final p = Paint()..style = PaintingStyle.stroke;
    for (var i = 0; i < 150; i++) {
      final y = size.height * rnd.nextDouble();
      final amp = size.height * (0.002 + rnd.nextDouble() * 0.006);
      final ph = rnd.nextDouble() * math.pi * 2;
      final dark = rnd.nextDouble() < 0.7;
      p
        ..strokeWidth = math.max(0.4, size.height * (0.0012 + rnd.nextDouble() * 0.003))
        ..color = (dark ? const Color(0xFF1B0C03) : const Color(0xFFD9A06A))
            .alphaD(dark ? 0.16 + rnd.nextDouble() * 0.14 : 0.10);
      final path = Path()..moveTo(0, y);
      for (var k = 1; k <= 16; k++) {
        final u = k / 16;
        path.lineTo(size.width * u,
            y + math.sin(u * math.pi * 3 + ph) * amp + math.sin(u * 17 + ph) * amp * 0.3);
      }
      canvas.drawPath(path, p);
    }
    // Yoritilish tekis: yuqori va pastki tomon bir xil (gradient yo'q).
    canvas.restore();
    // Qirra: tashqarida yorug', ichkarida qorong'u chiziq
    canvas.drawRRect(
      rr.deflate(1),
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.2
        ..color = const Color(0x22FFE3B8),
    );
  }

  @override
  bool shouldRepaint(covariant _WoodFramePainter old) => false;
}

class _SquarePainter extends CustomPainter {
  const _SquarePainter({
    required this.style,
    required this.light,
    required this.seed,
    required this.base,
  });

  final int style;
  final bool light;
  final int seed;
  final Color base;

  @override
  void paint(Canvas canvas, Size size) {
    final rect = Offset.zero & size;
    if (style == 2) {
      canvas.drawRect(rect, Paint()..color = base);
      return;
    }
    canvas.drawRect(
      rect,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            Color.lerp(base, Colors.white, 0.06)!,
            Color.lerp(base, Colors.black, 0.07)!,
          ],
        ).createShader(rect),
    );

    final rnd = math.Random(seed * 7919 + (light ? 1 : 2));
    final w = size.width;
    final h = size.height;

    if (style == 0) {
      final grain = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = math.max(0.6, w * 0.012)
        ..color = light ? const Color(0x1F8A5A2B) : const Color(0x33281406);
      for (var i = 0; i < 6; i++) {
        final y = h * (0.08 + i * 0.16) + rnd.nextDouble() * h * 0.05;
        final path = Path()
          ..moveTo(0, y)
          ..cubicTo(
            w * 0.3,
            y + (rnd.nextDouble() - 0.5) * h * 0.08,
            w * 0.65,
            y + (rnd.nextDouble() - 0.5) * h * 0.08,
            w,
            y + (rnd.nextDouble() - 0.5) * h * 0.06,
          );
        canvas.drawPath(path, grain);
      }
    } else {
      final vein = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = math.max(0.7, w * 0.014)
        ..color = light ? const Color(0x2A6B6B6B) : const Color(0x33D9E6DC);
      for (var i = 0; i < 2; i++) {
        final x0 = rnd.nextDouble() * w;
        final path = Path()
          ..moveTo(x0, 0)
          ..cubicTo(
            x0 + (rnd.nextDouble() - 0.5) * w,
            h * 0.3,
            x0 + (rnd.nextDouble() - 0.5) * w,
            h * 0.65,
            rnd.nextDouble() * w,
            h,
          );
        canvas.drawPath(path, vein);
      }
    }
  }

  @override
  bool shouldRepaint(covariant _SquarePainter old) =>
      old.style != style ||
      old.light != light ||
      old.seed != seed ||
      old.base != base;
}

/// Doska: tanlash, yurish mumkin bo'lgan kataklar, oxirgi yurish,
/// shoh ostidagi ogohlantirish. Ko'rinishi [style] ga bog'liq.
class ChessBoard extends StatefulWidget {
  const ChessBoard({
    super.key,
    required this.game,
    required this.onMoved,
    required this.pal,
    required this.style,
    this.lastFrom,
    this.lastTo,
    this.enabled = true,
    this.flipped = false,
    this.premoveColor,
    this.premoves = const [],
    this.onPremove,
  });

  /// Premove: raqib yurayotganda keyingi yurishni oldindan belgilash.
  final ch.Color? premoveColor;
  final List<(String, String)> premoves;
  final void Function(String? from, String? to)? onPremove;

  final bool flipped;
  final ch.Chess game;
  final void Function(MoveRecord) onMoved;
  final Pal pal;
  final int style;
  final String? lastFrom;
  final String? lastTo;
  final bool enabled;

  @override
  State<ChessBoard> createState() => _ChessBoardState();
}

class _ChessBoardState extends State<ChessBoard> {
  static const String _files = 'abcdefgh';

  String? _selected;
  List<String> _targets = [];
  List<Map<String, dynamic>> _selMoves = [];

  String _square(int row, int col) => widget.flipped
      ? '${_files[7 - col]}${row + 1}'
      : '${_files[col]}${8 - row}';

  void _clear() {
    _selected = null;
    _targets = [];
    _selMoves = [];
    _dragFrom = null;
    _dragActive = false;
    _hoverSq = null;
  }

  // ---- Figurani ushlab sudrash (drag and drop) ----
  String? _dragFrom; // ushlab olingan figura turgan katak
  bool _dragActive = false; // sichqoncha/barmoq haqiqatan siljidi
  Offset _dragPos = Offset.zero; // doska ichidagi joriy nuqta
  Offset _dragStart = Offset.zero;
  String? _hoverSq;
  bool _wasSelected = false;

  String? _sqAt(Offset p, double cell) {
    if (cell <= 0) return null;
    final col = (p.dx / cell).floor();
    final row = (p.dy / cell).floor();
    if (col < 0 || col > 7 || row < 0 || row > 7) return null;
    return _square(row, col);
  }

  bool get _premoveMode =>
      !widget.enabled &&
      widget.premoveColor != null &&
      widget.onPremove != null &&
      widget.game.turn != widget.premoveColor;

  ch.Color get _ownColor =>
      _premoveMode ? widget.premoveColor! : widget.game.turn;

  /// Premove rejimida: navbatdagi premovelar ketma-ket bajarilgan taxminiy pozitsiya.
  ch.Chess? _hypo() {
    final own = widget.premoveColor == ch.Color.WHITE ? 'w' : 'b';
    try {
      var g = ch.Chess.fromFEN(widget.game.fen);
      for (var i = 0; i <= widget.premoves.length; i++) {
        final parts = g.fen.split(' ');
        if (parts.length < 4) return null;
        parts[1] = own;
        parts[3] = '-';
        g = ch.Chess.fromFEN(parts.join(' '));
        if (i == widget.premoves.length) break;
        final pm = widget.premoves[i];
        final before = g.history.length;
        g.move({'from': pm.$1, 'to': pm.$2, 'promotion': 'q'});
        if (g.history.length == before) return null;
      }
      return g;
    } catch (_) {
      return null;
    }
  }

  String? _hKey;
  ch.Chess? _hVal;

  ch.Chess get _view {
    if (!_premoveMode) return widget.game;
    final key = '${widget.game.fen}|${widget.premoves}';
    if (key != _hKey) {
      _hKey = key;
      _hVal = _hypo();
    }
    return _hVal ?? widget.game;
  }

  List _movesFrom(String sq) {
    if (_premoveMode) {
      final g = _hypo();
      if (g == null) return const [];
      try {
        return g.moves({'verbose': true, 'square': sq}) as List;
      } catch (_) {
        return const [];
      }
    }
    return widget.game.moves({'verbose': true, 'square': sq}) as List;
  }

  void _select(String sq) {
    final moves = _movesFrom(sq);
    final list = [
      for (final m in moves) Map<String, dynamic>.from(m as Map),
    ];
    _selected = sq;
    _selMoves = list;
    _targets = [for (final m in list) m['to'] as String];
  }

  void _pDown(Offset p, double cell) {
    if (!widget.enabled && !_premoveMode) return;
    final sq = _sqAt(p, cell);
    if (sq == null) return;
    final game = _view;
    _wasSelected = _selected == sq;
    // Tanlangan figura bor va bu mumkin bo'lgan katak: oddiy bosib yurish.
    if (_selected != null && _targets.contains(sq)) {
      _onTap(sq);
      return;
    }
    final piece = game.get(sq);
    if (piece != null && piece.color == _ownColor) {
      setState(() {
        _select(sq);
        _dragFrom = sq;
        _dragActive = false;
        _dragStart = p;
        _dragPos = p;
        _hoverSq = sq;
      });
    } else {
      setState(_clear);
    }
  }

  void _pMove(Offset p, double cell) {
    if (_dragFrom == null) return;
    if (!_dragActive && (p - _dragStart).distance < 5) return;
    setState(() {
      _dragActive = true;
      _dragPos = p;
      _hoverSq = _sqAt(p, cell);
    });
  }

  void _pUp(Offset p, double cell) {
    final from = _dragFrom;
    if (from == null) return;
    if (_dragActive) {
      final target = _sqAt(p, cell);
      if (target != null && _targets.contains(target)) {
        _doMove(from, target);
        return;
      }
      setState(() {
        _dragActive = false;
        _dragFrom = null;
        _hoverSq = null;
        if (target != from) {
          _selected = null;
          _targets = [];
          _selMoves = [];
        }
      });
    } else {
      setState(() {
        _dragFrom = null;
        _hoverSq = null;
        if (_wasSelected) {
          _selected = null;
          _targets = [];
          _selMoves = [];
        }
      });
    }
  }

  void _pCancel() {
    if (_dragFrom == null) return;
    setState(() {
      _dragActive = false;
      _dragFrom = null;
      _hoverSq = null;
    });
  }

  void _onTap(String sq) {
    if (!widget.enabled && !_premoveMode) return;
    final game = _view;
    final from = _selected;

    if (from != null && _targets.contains(sq)) {
      _doMove(from, sq);
      return;
    }

    final piece = game.get(sq);
    if (piece != null && piece.color == _ownColor) {
      setState(() => _select(sq));
    } else {
      setState(_clear);
    }
  }

  void _doMove(String from, String sq) {
    final game = widget.game;
    if (_premoveMode) {
      setState(_clear);
      if (widget.premoves.length < 10) widget.onPremove!(from, sq);
      return;
    }
    {
      final mover = game.get(from);
      final target = game.get(sq);
      PieceKind? captured = target == null ? null : kindOf(target.type);
      if (captured == null &&
          mover != null &&
          mover.type == ch.PieceType.PAWN &&
          from[0] != sq[0]) {
        captured = PieceKind.pawn; // en passant
      }

      final candidates = _selMoves.where((m) => m['to'] == sq).toList();
      String? san;
      if (candidates.isNotEmpty) {
        final pick = candidates.firstWhere(
          (m) => candidates.length == 1 || m['promotion']?.toString() == 'q',
          orElse: () => candidates.first,
        );
        san = pick['san']?.toString();
      }

      final before = game.history.length;
      game.move({'from': from, 'to': sq, 'promotion': 'q'});
      if (game.history.length == before) {
        setState(_clear);
        return;
      }

      final record = MoveRecord(
        san: san ?? '$from$sq',
        from: from,
        to: sq,
        white: mover?.color == ch.Color.WHITE,
        captured: captured,
      );
      setState(_clear);
      Sfx.instance.playSan(record.san);
      widget.onMoved(record);
    }
  }

  String? _checkedKing() {
    final game = widget.game;
    if (!game.in_check) return null;
    for (var r = 0; r < 8; r++) {
      for (var c = 0; c < 8; c++) {
        final sq = _square(r, c);
        final p = game.get(sq);
        if (p != null && p.type == ch.PieceType.KING && p.color == game.turn) {
          return sq;
        }
      }
    }
    return null;
  }

  TextStyle _frameStyle(double frame) =>
      coordTextStyle(widget.pal.frameText, frame);

  @override
  Widget build(BuildContext context) {
    final pal = widget.pal;
    return RepaintBoundary(
      child: AspectRatio(
        aspectRatio: 1,
        child: LayoutBuilder(builder: (context, c) {
          final total = math.min(c.maxWidth, c.maxHeight);
          final frame = total * 0.05;
          final inner = total - frame * 2;
          final cell = inner / 8;
          final checked = _checkedKing();

          return Container(
            width: total,
            height: total,
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(total * 0.012),
              gradient: LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
                colors: [pal.frameA, pal.frameB],
              ),
              border: widget.style == 1
                  ? Border.all(
                      color: pal.frameLine,
                      width: math.max(1.5, total * 0.004),
                    )
                  : null,
              boxShadow: const [
                BoxShadow(
                  blurRadius: 24,
                  offset: Offset(0, 10),
                  color: Colors.black45,
                ),
              ],
            ),
            child: Stack(
              children: [
                if (widget.style == 0)
                  const Positioned.fill(
                    child: RepaintBoundary(
                      child: CustomPaint(painter: _WoodFramePainter()),
                    ),
                  ),
                for (var i = 0; i < 8; i++) ...[
                  Positioned(
                    left: 0,
                    top: frame + i * cell,
                    width: frame,
                    height: cell,
                    child: Center(
                      child: Text(widget.flipped ? '${i + 1}' : '${8 - i}',
                          style: _frameStyle(frame)),
                    ),
                  ),
                  Positioned(
                    left: frame + i * cell,
                    bottom: 0,
                    width: cell,
                    height: frame,
                    child: Center(
                      child: Text(_files[widget.flipped ? 7 - i : i],
                          style: _frameStyle(frame)),
                    ),
                  ),
                ],
                Positioned(
                  left: frame,
                  top: frame,
                  width: inner,
                  height: inner,
                  child: RawGestureDetector(
                    // Telefonda doska ustida sudrash sahifani aylantirmasligi uchun
                    gestures: {
                      EagerGestureRecognizer:
                          GestureRecognizerFactoryWithHandlers<
                              EagerGestureRecognizer>(
                        () => EagerGestureRecognizer(),
                        (_) {},
                      ),
                    },
                    child: Listener(
                      behavior: HitTestBehavior.opaque,
                      onPointerDown: (e) {
                        if (e.buttons == kSecondaryMouseButton) {
                          // O'ng tugma: premove ni bekor qilish
                          widget.onPremove?.call(null, null);
                          setState(_clear);
                          return;
                        }
                        _pDown(e.localPosition, cell);
                      },
                      onPointerMove: (e) => _pMove(e.localPosition, cell),
                      onPointerUp: (e) => _pUp(e.localPosition, cell),
                      onPointerCancel: (_) => _pCancel(),
                      child: DecoratedBox(
                        decoration: BoxDecoration(
                          border: Border.all(color: pal.frameLine, width: 1.2),
                        ),
                        child: Stack(
                          fit: StackFit.expand,
                          children: [
                            if (widget.style == 0)
                              const RepaintBoundary(
                                child: CustomPaint(painter: _WoodBoardPainter()),
                              ),
                            Column(
                              children: [
                                for (var r = 0; r < 8; r++)
                                  Expanded(
                                    child: Row(
                                      children: [
                                        for (var f = 0; f < 8; f++)
                                          Expanded(
                                              child: _cell(r, f, cell, checked)),
                                      ],
                                    ),
                                  ),
                              ],
                            ),
                            if (widget.style == 0)
                              const IgnorePointer(
                                child: CustomPaint(painter: _LacquerPainter()),
                              ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
                if (_dragActive && _dragFrom != null)
                  Positioned(
                    left: frame + _dragPos.dx - cell * 0.58,
                    top: frame + _dragPos.dy - cell * 0.58,
                    width: cell * 1.16,
                    height: cell * 1.16,
                    child: IgnorePointer(
                      child: Builder(builder: (_) {
                        final pc = _view.get(_dragFrom!);
                        if (pc == null) return const SizedBox.shrink();
                        return PieceView(
                          kind: kindOf(pc.type),
                          white: pc.color == ch.Color.WHITE,
                          size: cell * 1.16,
                          style: widget.style,
                        );
                      }),
                    ),
                  ),
              ],
            ),
          );
        }),
      ),
    );
  }

  Widget _cell(int row, int col, double cell, String? checked) {
    final sq = _square(row, col);
    final isLight = (row + col) % 2 == 0;
    final piece = (_premoveMode && widget.premoves.isNotEmpty ? _view : widget.game).get(sq);
    final isTarget = _targets.contains(sq);
    final isLast = sq == widget.lastFrom || sq == widget.lastTo;
    final isSel = sq == _selected;

    final isPremove = widget.premoves.any((m) => m.$1 == sq || m.$2 == sq);
    final hiddenPiece = _dragActive && sq == _dragFrom;
    final hover = _dragActive && sq == _hoverSq && isTarget;
    return ColoredBox(
      color: Colors.transparent,
      child: Stack(
        fit: StackFit.expand,
        children: [
          if (widget.style != 0)
            CustomPaint(
              painter: _SquarePainter(
                style: widget.style,
                light: isLight,
                seed: row * 8 + col,
                base: isLight ? widget.pal.boardLight : widget.pal.boardDark,
              ),
            ),
          if (isLast) const ColoredBox(color: Color(0x80CDD26A)),
          if (isSel) const ColoredBox(color: Color(0x99F6F669)),
          if (checked == sq)
            const DecoratedBox(
              decoration: BoxDecoration(
                gradient: RadialGradient(
                  colors: [Color(0xCCE53935), Color(0x00E53935)],
                ),
              ),
            ),
          if (isPremove)
            const ColoredBox(color: Color(0x88E8590C)),
          if (hover)
            DecoratedBox(
              decoration: BoxDecoration(
                border: Border.all(
                  color: const Color(0xCCFFFFFF),
                  width: cell * 0.06,
                ),
              ),
            ),
          if (isTarget && piece == null)
            Center(
              child: Container(
                width: cell * 0.3,
                height: cell * 0.3,
                decoration: const BoxDecoration(
                  shape: BoxShape.circle,
                  color: Color(0x55000000),
                ),
              ),
            ),
          if (isTarget && piece != null)
            Container(
              margin: EdgeInsets.all(cell * 0.04),
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                border: Border.all(
                  color: const Color(0x66000000),
                  width: cell * 0.08,
                ),
              ),
            ),
          if (piece != null && !hiddenPiece)
            Padding(
              padding: EdgeInsets.all(cell * 0.02),
              child: AnimatedScale(
                scale: isSel ? 1.08 : 1.0,
                duration: const Duration(milliseconds: 120),
                child: PieceView(
                  kind: kindOf(piece.type),
                  white: piece.color == ch.Color.WHITE,
                  size: cell * 0.96,
                  style: widget.style,
                ),
              ),
            ),
        ],
      ),
    );
  }
}

/// Tanlash oynasidagi kichik doska namunasi.
class BoardPreview extends StatelessWidget {
  const BoardPreview({super.key, required this.style, required this.size});
  final int style;
  final double size;

  @override
  Widget build(BuildContext context) {
    final pal = Pal.of(style, false);
    final cell = size / 4;

    (PieceKind, bool)? pieceAt(int r, int c) {
      if (r == 0 && c == 2) return (PieceKind.king, false);
      if (r == 1 && c == 1) return (PieceKind.knight, true);
      if (r == 2 && c == 3) return (PieceKind.pawn, false);
      if (r == 3 && c == 0) return (PieceKind.queen, true);
      return null;
    }

    return ClipRRect(
      borderRadius: BorderRadius.circular(10),
      child: SizedBox(
        width: size,
        height: size,
        child: Column(
          children: [
            for (var r = 0; r < 4; r++)
              Expanded(
                child: Row(
                  children: [
                    for (var c = 0; c < 4; c++)
                      Expanded(
                        child: Stack(
                          fit: StackFit.expand,
                          children: [
                            CustomPaint(
                              painter: _SquarePainter(
                                style: style,
                                light: (r + c) % 2 == 0,
                                seed: r * 4 + c,
                                base: (r + c) % 2 == 0
                                    ? pal.boardLight
                                    : pal.boardDark,
                              ),
                            ),
                            if (pieceAt(r, c) != null)
                              Padding(
                                padding: EdgeInsets.all(cell * 0.02),
                                child: PieceView(
                                  kind: pieceAt(r, c)!.$1,
                                  white: pieceAt(r, c)!.$2,
                                  size: cell * 0.96,
                                  style: style,
                                ),
                              ),
                          ],
                        ),
                      ),
                  ],
                ),
              ),
          ],
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// Soat: 0 = LCD, 1 = ag'dariladigan (flip) kartochkalar, 2 = klassik serif
// ---------------------------------------------------------------------------

const Color _redLow = Color(0xFFFF6B5E);

const Map<String, String> _digitSegs = {
  '0': 'abcdef',
  '1': 'bc',
  '2': 'abged',
  '3': 'abgcd',
  '4': 'fgbc',
  '5': 'afgcd',
  '6': 'afgedc',
  '7': 'abc',
  '8': 'abcdefg',
  '9': 'abcdfg',
};

Map<String, List<Offset>> _segPolys(double w, double h) {
  final t = h * 0.13;
  final g = h * 0.012;

  List<Offset> hor(double yc) {
    final x0 = t / 2 + g;
    final x1 = w - t / 2 - g;
    return [
      Offset(x0, yc),
      Offset(x0 + t / 2, yc - t / 2),
      Offset(x1 - t / 2, yc - t / 2),
      Offset(x1, yc),
      Offset(x1 - t / 2, yc + t / 2),
      Offset(x0 + t / 2, yc + t / 2),
    ];
  }

  List<Offset> ver(double xc, double y0, double y1) => [
        Offset(xc, y0),
        Offset(xc + t / 2, y0 + t / 2),
        Offset(xc + t / 2, y1 - t / 2),
        Offset(xc, y1),
        Offset(xc - t / 2, y1 - t / 2),
        Offset(xc - t / 2, y0 + t / 2),
      ];

  final top = t / 2;
  final mid = h / 2;
  final bot = h - t / 2;
  return {
    'a': hor(top),
    'g': hor(mid),
    'd': hor(bot),
    'f': ver(t / 2, top + g, mid - g),
    'b': ver(w - t / 2, top + g, mid - g),
    'e': ver(t / 2, mid + g, bot - g),
    'c': ver(w - t / 2, mid + g, bot - g),
  };
}

class _LcdPainter extends CustomPainter {
  const _LcdPainter({required this.text, required this.on, required this.off});
  final String text;
  final Color on;
  final Color off;

  @override
  void paint(Canvas canvas, Size size) {
    final dh = size.height * 0.62;
    final dw = dh * 0.52;
    final gap = dw * 0.28;
    final colw = dw * 0.4;
    final total = 4 * dw + 5 * gap + colw;
    var pos = (size.width - total) / 2;
    final cy = (size.height - dh) / 2;

    final onPaint = Paint()..color = on;
    final offPaint = Paint()..color = off;
    final glow = Paint()
      ..color = on.withAlpha(110)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3.5);

    for (final c in text.split('')) {
      if (c == ':') {
        final r = dh * 0.055;
        final cx = pos + colw / 2 + gap / 2;
        for (final yy in [cy + dh * 0.33, cy + dh * 0.67]) {
          canvas.drawCircle(Offset(cx, yy), r * 1.8, glow);
          canvas.drawCircle(Offset(cx, yy), r, onPaint);
        }
        pos += colw + gap * 2;
      } else {
        final segs = _digitSegs[c] ?? '';
        _segPolys(dw, dh).forEach((name, poly) {
          final path = Path()
            ..addPolygon([for (final p in poly) p.translate(pos, cy)], true);
          if (segs.contains(name)) {
            canvas.drawPath(path, glow);
            canvas.drawPath(path, onPaint);
          } else {
            canvas.drawPath(path, offPaint);
          }
        });
        pos += dw + gap;
      }
    }
  }

  @override
  bool shouldRepaint(covariant _LcdPainter old) =>
      old.text != text || old.on != on || old.off != off;
}

class ClockView extends StatelessWidget {
  const ClockView({
    super.key,
    required this.style,
    required this.seconds,
    required this.active,
    required this.low,
    this.width = 172,
  });

  final int style;
  final int seconds;
  final bool active;
  final bool low;
  final double width;

  Widget _lcd(String text) {
    return Container(
      decoration: BoxDecoration(
        color: const Color(0xFF0B140E),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
          color: active ? const Color(0xFF4DDB74) : const Color(0xFF1E3A28),
          width: 1.5,
        ),
      ),
      child: CustomPaint(
        painter: _LcdPainter(
          text: text,
          on: low ? _redLow : const Color(0xFF6BFF8E),
          off: const Color(0xFF143021),
        ),
      ),
    );
  }

  Widget _flip(String text) {
    Widget tile(String d) => Container(
          width: 33,
          height: 50,
          decoration: BoxDecoration(
            color: const Color(0xFF2A2A30),
            borderRadius: BorderRadius.circular(6),
            border: Border.all(
              color: active ? const Color(0xFFE2B455) : const Color(0xFF3A3A42),
              width: 1.2,
            ),
          ),
          child: Stack(
            alignment: Alignment.center,
            children: [
              Text(
                d,
                style: TextStyle(
                  fontSize: 31,
                  height: 1.0,
                  fontWeight: FontWeight.w700,
                  color: low ? _redLow : const Color(0xFFF3E9D0),
                ),
              ),
              Container(height: 1.6, color: const Color(0xFF0A0A0C)),
            ],
          ),
        );

    Widget dot() => Container(
          width: 5,
          height: 5,
          decoration: const BoxDecoration(
            shape: BoxShape.circle,
            color: Color(0xFFE9DDBC),
          ),
        );

    return Center(
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          tile(text[0]),
          const SizedBox(width: 4),
          tile(text[1]),
          SizedBox(
            width: 14,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [dot(), const SizedBox(height: 12), dot()],
            ),
          ),
          tile(text[3]),
          const SizedBox(width: 4),
          tile(text[4]),
        ],
      ),
    );
  }

  Widget _classic(String text) {
    return Container(
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0xFF4A2F1B), Color(0xFF2B1A0F)],
        ),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
          color: active ? const Color(0xFFE2B455) : const Color(0xFF7A5A2A),
          width: 1.6,
        ),
      ),
      child: Center(
        child: Text(
          text,
          style: TextStyle(
            fontFamily: 'Georgia',
            fontFamilyFallback: const ['Times New Roman', 'serif'],
            fontSize: 32,
            fontWeight: FontWeight.w700,
            letterSpacing: 2,
            fontFeatures: const [FontFeature.tabularFigures()],
            color: low ? _redLow : const Color(0xFFF0D79A),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final text = formatClock(seconds);
    final Widget inner;
    switch (style) {
      case 1:
        inner = _flip(text);
        break;
      case 2:
        inner = _classic(text);
        break;
      default:
        inner = _lcd(text);
    }
    return SizedBox(
      width: width,
      height: width * 60 / 176,
      child: FittedBox(
        fit: BoxFit.contain,
        child: SizedBox(width: 176, height: 60, child: inner),
      ),
    );
  }
}

