class PlayerCard extends StatelessWidget {
  const PlayerCard({
    super.key,
    required this.pal,
    required this.boardStyle,
    required this.clockStyle,
    required this.name,
    required this.rating,
    required this.subtitle,
    required this.white,
    required this.captured,
    required this.advantage,
    required this.seconds,
    required this.active,
    this.avatar,
    this.initials = '',
  });

  final Uint8List? avatar;
  final String initials;
  final Pal pal;
  final int boardStyle;
  final int clockStyle;
  final String name;
  final String rating;
  final String subtitle;
  final bool white;

  /// Bu o'yinchi olgan (raqibning) donalari.
  final List<PieceKind> captured;
  final int advantage;
  final int seconds;
  final bool active;

  @override
  Widget build(BuildContext context) {
    final sorted = [...captured]
      ..sort((a, b) => pieceValue(b).compareTo(pieceValue(a)));

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
      decoration: BoxDecoration(
        color: pal.card,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: active ? pal.accent : pal.cardBorder,
          width: active ? 1.6 : 1,
        ),
        boxShadow: active
            ? [BoxShadow(color: pal.accent.withAlpha(0x40), blurRadius: 12)]
            : null,
      ),
      child: Row(
        children: [
          avatar != null || initials.isNotEmpty
              ? AvatarView(
                  size: 46,
                  initials: initials,
                  pal: pal,
                  bytes: avatar,
                )
              : Container(
                  width: 46,
                  height: 46,
                  padding: const EdgeInsets.all(4),
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: white ? pal.avatarWhite : pal.avatarBlack,
                    border: Border.all(color: pal.cardBorder),
                  ),
                  child: PieceView(
                    kind: PieceKind.king,
                    white: white,
                    size: 38,
                    style: boardStyle,
                  ),
                ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Row(
                  children: [
                    Flexible(
                      child: Text(
                        name,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          fontWeight: FontWeight.w700,
                          fontSize: 16,
                          color: pal.text,
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 8,
                        vertical: 2,
                      ),
                      decoration: BoxDecoration(
                        color: pal.accentSoft,
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: pal.accent),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(Icons.star_rounded, size: 14, color: pal.accent),
                          const SizedBox(width: 3),
                          Text(
                            rating,
                            style: TextStyle(
                              fontSize: 12.5,
                              fontWeight: FontWeight.w700,
                              color: pal.text,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 2),
                Text(
                  subtitle,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(fontSize: 12, color: pal.subtext),
                ),
                if (sorted.isNotEmpty)
                  Padding(
                    padding: const EdgeInsets.only(top: 4),
                    child: SizedBox(
                      height: 20,
                      child: FittedBox(
                        fit: BoxFit.scaleDown,
                        alignment: Alignment.centerLeft,
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            for (final k in sorted)
                              Align(
                                widthFactor: 0.55,
                                child: PieceView(
                                  kind: k,
                                  white: !white,
                                  size: 20,
                                  style: boardStyle,
                                ),
                              ),
                            if (advantage > 0)
                              Padding(
                                padding: const EdgeInsets.only(left: 12),
                                child: Text(
                                  '+$advantage',
                                  style: TextStyle(
                                    fontSize: 12,
                                    fontWeight: FontWeight.w700,
                                    color: pal.subtext,
                                  ),
                                ),
                              ),
                          ],
                        ),
                      ),
                    ),
                  ),
              ],
            ),
          ),
          const SizedBox(width: 8),
          ClockView(
            style: clockStyle,
            seconds: seconds,
            active: active,
            low: seconds <= 30,
            width: 158,
          ),
        ],
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// Yurishlar ro'yxati
// ---------------------------------------------------------------------------

class MoveListPanel extends StatefulWidget {
  const MoveListPanel({
    super.key,
    required this.pal,
    required this.moves,
    required this.title,
    required this.emptyText,
  });

  final Pal pal;
  final List<MoveRecord> moves;
  final String title;
  final String emptyText;

  @override
  State<MoveListPanel> createState() => _MoveListPanelState();
}

class _MoveListPanelState extends State<MoveListPanel> {
  final ScrollController _controller = ScrollController();

  @override
  void didUpdateWidget(covariant MoveListPanel oldWidget) {
    super.didUpdateWidget(oldWidget);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_controller.hasClients) {
        _controller.jumpTo(_controller.position.maxScrollExtent);
      }
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  Widget _moveCell(MoveRecord? m, bool latest) {
    final pal = widget.pal;
    return Expanded(
      child: Container(
        margin: const EdgeInsets.symmetric(horizontal: 2, vertical: 1),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(8),
          color: latest ? pal.accentSoft : null,
        ),
        child: Text(
          m?.san ?? '',
          style: TextStyle(
            fontSize: 14,
            fontWeight: latest ? FontWeight.w700 : FontWeight.w500,
            color: pal.text,
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final pal = widget.pal;
    final moves = widget.moves;
    final rows = (moves.length + 1) ~/ 2;

    return Container(
      decoration: BoxDecoration(
        color: pal.card,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: pal.cardBorder),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
            child: Row(
              children: [
                Icon(Icons.format_list_numbered, size: 20, color: pal.accent),
                const SizedBox(width: 8),
                Text(
                  widget.title,
                  style: TextStyle(
                    fontWeight: FontWeight.w700,
                    fontSize: 15,
                    color: pal.text,
                  ),
                ),
                const Spacer(),
                Text(
                  '${moves.length}',
                  style: TextStyle(color: pal.subtext, fontSize: 13),
                ),
              ],
            ),
          ),
          Divider(height: 1, color: pal.cardBorder),
          Expanded(
            child: moves.isEmpty
                ? Center(
                    child: Text(
                      widget.emptyText,
                      style: TextStyle(color: pal.subtext),
                    ),
                  )
                : ListView.builder(
                    controller: _controller,
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 6,
                    ),
                    itemCount: rows,
                    itemBuilder: (context, i) {
                      final white = moves[2 * i];
                      final black = 2 * i + 1 < moves.length
                          ? moves[2 * i + 1]
                          : null;
                      return Row(
                        children: [
                          SizedBox(
                            width: 34,
                            child: Text(
                              '${i + 1}.',
                              style: TextStyle(
                                color: pal.subtext,
                                fontSize: 13,
                              ),
                            ),
                          ),
                          _moveCell(white, 2 * i == moves.length - 1),
                          _moveCell(black, 2 * i + 1 == moves.length - 1),
                        ],
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }
}

